*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/calendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.contnId;
//var objTpCd;
scwin.vCurDate;
scwin.gLdMktTp = js_market;
scwin.vScrenID = "ULDSTF30353.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_single_read = function() {
    //투자유의안내 개별조회

    trs_Read.Action = "/IRMgt.do?method=readInvestInfo&CONTN_ID=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_NoticeContentSingle,O:pOutput2=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_update = function() {
    //투자유의안내 수정

    if (tbox_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_title, 200, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_content.Text == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_content.focus();
        return;
    }
    if (!scwin.checkMaxLength2(tarea_content, 2000, "내용")) {
        tarea_content.text = "";
        tarea_content.focus();
        return false;
    }
    var rtn = confirm('위사항을 수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_NoticeContentSingle.setCellData(dts_NoticeContentSingle.getRowPosition(), "LD_MKT_TP_CD", rdo_mkt_gubun.getValue());
        trs_Update.Action = "/IRMgt.do?method=modifyInvestInfo&CONTN_ID=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Update.KeyName = "toinb_dataid4";
        trs_Update.KeyValue = "JSP(I:pInput1=dts_NoticeContentSingle,I:pInput2=dts_fileList)";
        trs_Update.Post();
    }
};
scwin.fn_save = function() {
    //투자유의안내 등록

    if (tbox_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_title, 200, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_content.Text == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_content.focus();
        return;
    }
    if (!scwin.checkMaxLength2(tarea_content, 2000, "내용")) {
        tarea_content.text = "";
        tarea_content.focus();
        return false;
    }
    var rtn = confirm('위사항을 입력 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_Save.Action = "/IRMgt.do?method=registerInvestInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_noticeInfo,I:pFile1=dts_fileList)";
        trs_Save.Post();
    }
};
scwin.fn_delete = function() {
    //투자유의안내 삭제

    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        //dts_NoticeDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_NoticeDelete.insertRow();
        dts_NoticeDelete.setCellData(1, "CONTN_ID", scwin.contnId);
        trs_Delete.Action = "/IRMgt.do?method=removeInvestInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput=dts_NoticeDelete)";
        trs_Delete.Post();
    }
};
scwin.fn_SetIrInfoHeader = function() {
    // CUD용 Header
    dts_noticeInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NOTICECONTENT_NOTEINFO_INOUT";
    dts_noticeInfo.Reset();
    dts_noticeInfo.insertRow();
};

//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?file_id=" + scwin.contnId + "&attach_seq=" + attach_seq + "&gubun=2";
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_save_onclick = function() {
    if (scwin.contnId == "input") {
        scwin.fn_save();
    } else {
        scwin.fn_update();
    }
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "투자유의안내등록"));
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "투자유의안내등록"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "투자유의안내수정"));
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "투자유의안내수정"));
    $c.win.alert(trs_Update.ErrorMsg);
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "투자유의안내삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "투자유의안내삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.btn_lineadd_onclick = function() {
    if (dts_fileList.getTotalRow() == 5) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.getValue();
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_userlist_OnClick = function(row, colid) {
    if (row == 0) return;
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.showObj(tbox_user, false);
    scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
    getContnId = $c.frame.path("../").fn_getContnId;
    scwin.contnId = getContnId();
    if (scwin.contnId != "input") {
        getSysCode = $c.frame.path("../").fn_getSysCode;
        //objTpCd = getSysCode();
        //showObj(panel_mkt_gubun,false);

        scwin.fn_single_read();

        //if(objTpCd == "1" || objTpCd == "6"){
        rdo_mkt_gubun.setValue(dts_NoticeContentSingle.getCellData(dts_NoticeContentSingle.getRowPosition(), "LD_MKT_TP_CD"));
        //}

    } else {

        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        scwin.fn_SetIrInfoHeader();
        $c.stf.showObj(btn_delete, false);
        var today = $c.ut.cGetToday2();
        var nextMonDay = $c.ut.calcMonth(today, 1);
        tbox_user.setValue(js_dep_nm);
        dts_noticeInfo.setCellData(dts_noticeInfo.getRowPosition(), "WRTR_EMP_NO", js_emp_no);
        if (js_market == "9") {
            $c.stf.setObjectValue(rdo_mkt_gubun, "9");
        } else {
            $c.stf.setObjectValue(rdo_mkt_gubun, js_market);
        }
    }
};
